public class Solution {

// Method to find the smallest number in the set of negative numbers
  public static int findSmallestNumber(Set<Integer> negativeNumbers) {
    int smallestNumber = Integer.MAX_VALUE;
    for (Integer num : negativeNumbers) {
      if (num < smallestNumber) {
        smallestNumber = num;
      }
    }
    return smallestNumber;
  }

